import React from 'react';
import { Link } from 'react-router-dom';
import { ShoppingBag, ArrowLeft } from 'lucide-react';
import { useCart } from '../context/CartContext';
import { formatPrice } from '../utils/helpers';

const CartPage = () => {
    const { cartItems, cartTotal, removeFromCart, updateQuantity, clearCart } = useCart();

    if (cartItems.length === 0) {
        return (
            <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center">
                <div className="text-center space-y-8">
                    <div className="relative">
                        <ShoppingBag size={100} strokeWidth={0.5} className="text-gray-200" />
                        <div className="absolute inset-0 bg-blue-600/10 blur-3xl rounded-full" />
                    </div>
                    <div className="space-y-4">
                        <p className="font-heading text-2xl uppercase tracking-widest text-gray-900">Your cart is empty</p>
                        <p className="text-[10px] uppercase tracking-widest text-gray-400 font-bold max-w-xs">
                            Start exploring our collection of laptops and accessories
                        </p>
                    </div>
                    <Link
                        to="/"
                        className="group relative px-10 py-4 border-2 border-gray-900 rounded-full overflow-hidden transition-all duration-500 hover:shadow-2xl hover:-translate-y-1 hover:border-blue-600"
                    >
                        <div className="absolute inset-0 bg-gray-900 top-full group-hover:top-0 transition-all duration-500" />
                        <span className="relative z-10 text-[10px] uppercase font-black tracking-widest text-gray-900 group-hover:text-white transition-colors duration-500">Start Shopping</span>
                    </Link>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Header */}
            <div className="bg-gray-50/80 backdrop-blur-md sticky top-0 z-40 px-6 py-4 flex items-center gap-4">
                <Link to="/" className="p-2 hover:bg-white rounded-full shadow-sm transition-all active:scale-95">
                    <ArrowLeft size={20} className="text-gray-900" />
                </Link>
                <h1 className="font-heading text-xl text-gray-900 truncate">Shopping Cart</h1>
            </div>

            {/* Content */}
            <div className="max-w-4xl mx-auto px-4 py-8">
                <div className="bg-white rounded-2xl shadow-sm overflow-hidden">
                    {/* Cart Items */}
                    <div className="divide-y divide-gray-100">
                        {cartItems.map((item) => (
                            <div key={item.id} className="p-6 flex gap-6">
                                {/* Image */}
                                <div className="w-24 h-24 flex-shrink-0 bg-gray-100 rounded-lg overflow-hidden">
                                    <img
                                        src={Array.isArray(item.imageUrls) ? item.imageUrls[0] : item.imageUrls}
                                        alt={item.name}
                                        className="w-full h-full object-cover"
                                    />
                                </div>

                                {/* Info */}
                                <div className="flex-1">
                                    <div className="flex justify-between items-start mb-2">
                                        <div>
                                            <h3 className="font-heading text-lg text-gray-900 uppercase leading-tight">
                                                {item.name}
                                            </h3>
                                            <p className="text-[10px] uppercase tracking-[0.2em] text-blue-600 font-black mt-1">
                                                {item.category || 'Gadget'}
                                            </p>
                                        </div>
                                        <button
                                            onClick={() => removeFromCart(item.id)}
                                            className="text-gray-400 hover:text-red-500 transition-colors p-1"
                                            title="Remove item"
                                        >
                                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 012.838.283L6.838 21l-4.418-4.418a2 2 0 010-2.828 0L7 7h10a2 2 0 002 2v10a2 2 0 002-2z" />
                                            </svg>
                                        </button>
                                    </div>

                                    <div className="flex items-center justify-between">
                                        {/* Price */}
                                        <p className="font-body font-black text-gray-900 text-xl tracking-tight">
                                            {formatPrice(item.price)}
                                        </p>

                                        {/* Quantity Controls */}
                                        <div className="flex items-center gap-3 bg-gray-50 border border-gray-200 rounded-full px-3 py-2">
                                            <button
                                                onClick={() => updateQuantity(item.id, -1)}
                                                className="w-8 h-8 flex items-center justify-center rounded-full bg-white border border-gray-200 text-gray-400 hover:text-gray-900 transition-all"
                                            >
                                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" />
                                                </svg>
                                            </button>
                                            <span className="text-sm font-bold w-8 text-center text-gray-900">{item.quantity}</span>
                                            <button
                                                onClick={() => updateQuantity(item.id, 1)}
                                                className="w-8 h-8 flex items-center justify-center rounded-full bg-white border border-gray-200 text-gray-400 hover:text-gray-900 transition-all"
                                            >
                                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-16H4" />
                                                </svg>
                                            </button>
                                        </div>
                                    </div>

                                    {/* Item Total */}
                                    <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                                        <span className="text-[10px] uppercase tracking-[0.2em] text-gray-400 font-bold">Subtotal</span>
                                        <p className="font-body font-black text-gray-900 text-lg tracking-tight">
                                            {formatPrice(item.price * item.quantity)}
                                        </p>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Cart Summary */}
                    <div className="p-6 bg-gray-50 border-t border-gray-200">
                        <div className="space-y-3 mb-6">
                            <div className="flex items-center justify-between text-gray-900">
                                <span className="text-[10px] uppercase tracking-[0.2em] text-gray-400 font-bold">Subtotal</span>
                                <span className="text-lg font-body font-bold text-gray-900 tracking-tight">
                                    {formatPrice(cartTotal)}
                                </span>
                            </div>
                            <div className="flex items-center justify-between text-gray-900 pt-3 border-t border-gray-200">
                                <span className="text-[11px] uppercase tracking-[0.3em] font-black">Total</span>
                                <span className="text-2xl font-body font-black text-blue-600 tracking-tight">
                                    {formatPrice(cartTotal)}
                                </span>
                            </div>
                        </div>

                        <div className="flex gap-4">
                            <button
                                onClick={clearCart}
                                className="flex-1 px-6 py-3 border-2 border-gray-300 rounded-full text-[10px] uppercase font-bold tracking-widest text-gray-600 hover:bg-gray-100 transition-all"
                            >
                                Clear Cart
                            </button>
                            <Link
                                to="/"
                                className="flex-1 px-6 py-3 bg-gray-900 hover:bg-blue-600 text-white rounded-full text-[10px] uppercase font-bold tracking-widest transition-all text-center"
                            >
                                Continue Shopping
                            </Link>
                        </div>
                    </div>
                </div>

                {/* Checkout Notice */}
                <div className="mt-6 text-center">
                    <p className="text-sm text-gray-500">
                        Complete your order by clicking the cart icon in the navigation or use the cart drawer.
                    </p>
                </div>
            </div>
        </div>
    );
};

export default CartPage;
