import React, { useState } from 'react';
import { X, Minus, Plus, ShoppingBag, MapPin, User, Phone, Truck, CheckCircle, Loader2, Trash2 } from 'lucide-react';
import { useCart } from '../context/CartContext';

const CartDrawer = () => {
    const { isCartOpen, setIsCartOpen, cartItems, updateQuantity, removeFromCart, cartTotal } = useCart();
    const [isLocating, setIsLocating] = useState(false);
    const [focusedField, setFocusedField] = useState(null);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [customerInfo, setCustomerInfo] = useState({
        name: '',
        phone: '',
        location: ''
    });
    const [deliveryMethod, setDeliveryMethod] = useState('delivery'); // 'delivery' or 'pickup'
    const DELIVERY_FEE = 0; // Finalized on WhatsApp
    const WHATSAPP_NUMBER = '233201534711'; // 0201534711 in international format

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setCustomerInfo(prev => ({ ...prev, [name]: value }));
    };

    const handleFocus = (field) => setFocusedField(field);
    const handleBlur = () => setFocusedField(null);

    const handleGetLocation = () => {
        if (!navigator.geolocation) {
            alert("Geolocation is not supported");
            return;
        }
        setIsLocating(true);
        navigator.geolocation.getCurrentPosition(
            (pos) => {
                const { latitude, longitude } = pos.coords;
                setCustomerInfo(prev => ({ ...prev, location: `GPS: ${latitude.toFixed(6)}, ${longitude.toFixed(6)}` }));
                setIsLocating(false);
            },
            () => {
                alert("Unable to get location");
                setIsLocating(false);
            }
        );
    };

    const handleCheckout = async () => {
        if (cartItems.length === 0) return;

        if (!customerInfo.name || !customerInfo.phone || (deliveryMethod === 'delivery' && !customerInfo.location)) {
            alert('Please fill in your contact and location details.');
            return;
        }

        setIsSubmitting(true);

        try {
            // Generate order number
            const orderNumber = 'LC' + Date.now().toString().slice(-8);

            // WhatsApp message
            let message = `🛍️ *NEW ORDER - LAPTOP CONNECT*\n\n`;
            message += `━━━━━━━━━━━━━━━━━━━━━\n\n`;
            message += `*Order Number:* ${orderNumber}\n`;
            message += `👤 *Customer Details*\n`;
            message += `Name: ${customerInfo.name}\n`;
            message += `Phone: ${customerInfo.phone}\n`;
            message += `Method: ${deliveryMethod === 'delivery' ? '🚚 Delivery' : '🏪 Pickup'}\n`;

            if (deliveryMethod === 'delivery') {
                message += `Location: ${customerInfo.location}\n`;
                if (customerInfo.location.includes('GPS:')) {
                    const coords = customerInfo.location.replace('GPS: ', '').split(', ');
                    message += `📍 Map: https://www.google.com/maps/search/?api=1&query=${coords[0]},${coords[1]}\n`;
                }
            }

            message += `\n📦 *Order Items*\n`;
            message += `━━━━━━━━━━━━━━━━━━━━━\n`;
            cartItems.forEach((item, index) => {
                const imageUrl = Array.isArray(item.imageUrls) ? item.imageUrls[0] : item.imageUrls;
                message += `\n${index + 1}. ${item.name}\n`;
                message += `   Qty: ${item.quantity} × GHS ${item.price.toLocaleString()}.00\n`;
                message += `   Subtotal: GHS ${(item.price * item.quantity).toLocaleString()}.00\n`;
            });

            message += `\n━━━━━━━━━━━━━━━━━━━━━\n`;
            message += `💰 *Order Summary*\n`;
            message += `Subtotal: GHS ${cartTotal.toLocaleString()}.00\n`;
            message += `Delivery: ${deliveryMethod === 'delivery' ? 'TBD (Discuss on WhatsApp)' : 'GHS 0.00'}\n`;
            message += `━━━━━━━━━━━━━━━━━━━━━\n`;
            message += `*TOTAL: GHS ${cartTotal.toLocaleString()}.00*\n\n`;
            message += `Thank you for your order! 🙏`;

            const encodedMessage = encodeURIComponent(message);
            window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodedMessage}`, '_blank');

            // Clear cart and close drawer
            localStorage.removeItem('laptop_connect_cart');
            setIsCartOpen(false);
            window.location.reload();

        } catch (error) {
            console.error('Checkout error:', error);
            alert('Failed to process order. Please check your connection.');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <>
            {/* Overlay */}
            <div
                className={`fixed inset-0 bg-gray-900/40 backdrop-blur-sm z-[150] transition-opacity duration-500 ${isCartOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
                onClick={() => setIsCartOpen(false)}
            />

            {/* Drawer */}
            <div
                className={`fixed top-0 right-0 h-full w-[450px] max-w-full bg-gray-50 z-[160] shadow-[-20px_0_60px_rgba(0,0,0,0.1)] flex flex-col transition-transform duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] ${isCartOpen ? 'translate-x-0' : 'translate-x-full'}`}
            >
                {/* Header */}
                <div className="flex items-center justify-between px-8 py-8 border-b border-gray-200 bg-gradient-to-b from-white/50 to-transparent">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-xl bg-blue-600/10 flex items-center justify-center text-blue-600">
                            <ShoppingBag size={20} />
                        </div>
                        <div>
                            <h2 className="font-heading text-xl uppercase tracking-tight text-gray-900 leading-none">Your Cart</h2>
                            <p className="text-[9px] uppercase tracking-[0.3em] text-gray-400 font-bold mt-1">
                                {cartItems.length} {cartItems.length === 1 ? 'item' : 'items'}
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={() => setIsCartOpen(false)}
                        className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 text-gray-400 hover:text-gray-900 transition-all"
                    >
                        <X size={20} />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto no-scrollbar p-8">
                    {cartItems.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-full text-center space-y-8 animate-fade-in">
                            <div className="relative">
                                <ShoppingBag size={100} strokeWidth={0.5} className="text-gray-200" />
                                <div className="absolute inset-0 bg-blue-600/10 blur-3xl rounded-full" />
                            </div>
                            <div className="space-y-4">
                                <p className="font-heading text-2xl uppercase tracking-widest text-gray-900">Your cart is empty</p>
                                <p className="text-[10px] uppercase tracking-widest text-gray-400 font-bold max-w-xs">
                                    Start exploring our collection of laptops and accessories
                                </p>
                            </div>
                            <button
                                onClick={() => setIsCartOpen(false)}
                                className="group relative px-10 py-4 border-2 border-gray-900 rounded-full overflow-hidden transition-all duration-500 hover:shadow-2xl hover:-translate-y-1 hover:border-blue-600"
                            >
                                <div className="absolute inset-0 bg-gray-900 top-full group-hover:top-0 transition-all duration-500" />
                                <span className="relative z-10 text-[10px] uppercase font-black tracking-widest text-gray-900 group-hover:text-white transition-colors duration-500">Start Shopping</span>
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-8">
                            {cartItems.map((item) => {
                                const imageUrl = Array.isArray(item.imageUrls) ? item.imageUrls[0] : item.imageUrls;
                                return (
                                    <div key={item.id} className="group flex gap-8 animate-fade-in relative">
                                        {/* Image Area */}
                                        <div className="w-28 aspect-square flex-shrink-0 bg-white border border-gray-200 rounded-xl overflow-hidden shadow-sm group-hover:shadow-md transition-shadow duration-500">
                                            <img
                                                src={imageUrl}
                                                alt={item.name}
                                                className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                                            />
                                        </div>

                                        {/* Info Area */}
                                        <div className="flex-1 flex flex-col justify-between py-0.5">
                                            <div className="space-y-1">
                                                <div className="flex justify-between items-start">
                                                    <span className="text-[9px] uppercase tracking-[0.2em] text-blue-600 font-black">{item.category || 'Gadget'}</span>
                                                    <button
                                                        onClick={() => removeFromCart(item.id)}
                                                        className="text-gray-300 hover:text-red-500 transition-colors p-1"
                                                        title="Remove item"
                                                    >
                                                        <Trash2 size={14} />
                                                    </button>
                                                </div>
                                                <h3 className="font-heading text-base text-gray-900 uppercase leading-tight tracking-tight group-hover:text-blue-600 transition-colors duration-500">
                                                    {item.name}
                                                </h3>
                                            </div>

                                            <div className="flex items-center justify-between pt-4">
                                                {/* Quantity Selector */}
                                                <div className="flex items-center gap-4 bg-white border border-gray-200 px-3 py-1.5 rounded-full shadow-sm hover:shadow-md transition-all duration-500">
                                                    <button
                                                        onClick={() => updateQuantity(item.id, -1)}
                                                        className="w-6 h-6 flex items-center justify-center rounded-full bg-gray-50 border border-gray-200 text-gray-400 hover:text-gray-900 transition-all"
                                                    >
                                                        <Minus size={12} />
                                                    </button>
                                                    <span className="text-[11px] font-black w-4 text-center text-gray-900">{item.quantity}</span>
                                                    <button
                                                        onClick={() => updateQuantity(item.id, 1)}
                                                        className="w-6 h-6 flex items-center justify-center rounded-full bg-gray-50 border border-gray-200 text-gray-400 hover:text-gray-900 transition-all"
                                                    >
                                                        <Plus size={12} />
                                                    </button>
                                                </div>

                                                {/* Price */}
                                                <p className="font-body font-black text-gray-900 text-[15px] tracking-tighter">
                                                    GHS {(item.price * item.quantity).toLocaleString()}.00
                                                </p>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>

                {/* Footer with Form */}
                <div className="p-6 md:p-8 border-t border-gray-200 bg-white shadow-[0_-20px_50px_rgba(0,0,0,0.03)] space-y-5">
                    {cartItems.length > 0 && (
                        <div className="space-y-5">
                            {/* Delivery Method Toggle */}
                            <div className="flex p-1 bg-gray-50 border border-gray-200 rounded-2xl">
                                <button
                                    onClick={() => setDeliveryMethod('delivery')}
                                    className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-[10px] uppercase font-bold tracking-widest transition-all ${deliveryMethod === 'delivery' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-400'}`}
                                >
                                    <Truck size={14} />
                                    Delivery
                                </button>
                                <button
                                    onClick={() => setDeliveryMethod('pickup')}
                                    className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-[10px] uppercase font-bold tracking-widest transition-all ${deliveryMethod === 'pickup' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-400'}`}
                                >
                                    <ShoppingBag size={14} />
                                    Pickup
                                </button>
                            </div>

                            <div className="space-y-3">
                                {/* Name Input */}
                                <div className={`relative transition-all duration-300 ${focusedField === 'name' ? 'scale-[1.02]' : ''}`}>
                                    <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">
                                        <User size={18} strokeWidth={1.5} />
                                    </div>
                                    <input
                                        type="text"
                                        name="name"
                                        value={customerInfo.name}
                                        onChange={handleInputChange}
                                        onFocus={() => handleFocus('name')}
                                        onBlur={handleBlur}
                                        placeholder="Full Name"
                                        className="w-full bg-gray-50 border-2 border-gray-200 rounded-full pl-12 pr-6 py-3 text-[11px] uppercase tracking-widest focus:border-blue-600 focus:bg-white focus:outline-none focus:shadow-lg transition-all"
                                    />
                                </div>

                                {/* Phone Input */}
                                <div className={`relative transition-all duration-300 ${focusedField === 'phone' ? 'scale-[1.02]' : ''}`}>
                                    <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">
                                        <Phone size={18} strokeWidth={1.5} />
                                    </div>
                                    <input
                                        type="tel"
                                        name="phone"
                                        value={customerInfo.phone}
                                        onChange={handleInputChange}
                                        onFocus={() => handleFocus('phone')}
                                        onBlur={handleBlur}
                                        placeholder="Phone Number"
                                        className="w-full bg-gray-50 border-2 border-gray-200 rounded-full pl-12 pr-6 py-3 text-[11px] uppercase tracking-widest focus:border-blue-600 focus:bg-white focus:outline-none focus:shadow-lg transition-all"
                                    />
                                </div>

                                {/* Location Input - Only show for Delivery */}
                                {deliveryMethod === 'delivery' && (
                                    <div className={`relative transition-all duration-300 ${focusedField === 'location' ? 'scale-[1.02]' : ''}`}>
                                        <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">
                                            <MapPin size={18} strokeWidth={1.5} />
                                        </div>
                                        <input
                                            type="text"
                                            name="location"
                                            value={customerInfo.location}
                                            onChange={handleInputChange}
                                            onFocus={() => handleFocus('location')}
                                            onBlur={handleBlur}
                                            placeholder="Delivery Location"
                                            className="w-full bg-gray-50 border-2 border-gray-200 rounded-full pl-12 pr-20 py-3 text-[11px] uppercase tracking-widest focus:border-blue-600 focus:bg-white focus:outline-none focus:shadow-lg transition-all"
                                        />
                                        <button
                                            onClick={handleGetLocation}
                                            disabled={isLocating}
                                            className="absolute right-2 top-1/2 -translate-y-1/2 px-3 py-1.5 bg-blue-600/10 text-blue-600 hover:bg-blue-600 hover:text-white rounded-full text-[9px] uppercase tracking-widest font-bold transition-all disabled:opacity-50"
                                        >
                                            {isLocating ? '...' : 'GPS'}
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    <div className="space-y-2 pt-4 border-t border-gray-200">
                        {cartItems.length > 0 && (
                            <>
                                <div className="flex items-center justify-between text-gray-900">
                                    <span className="text-[10px] uppercase tracking-[0.2em] text-gray-400 font-bold">Subtotal</span>
                                    <span className="text-base font-body font-bold text-gray-900 tracking-tight">
                                        GHS {cartTotal.toLocaleString()}.00
                                    </span>
                                </div>
                                <div className="flex items-center justify-between text-gray-900">
                                    <div className="flex items-center gap-2">
                                        <Truck size={14} className="text-blue-600" />
                                        <span className="text-[10px] uppercase tracking-[0.2em] text-gray-400 font-bold">Delivery</span>
                                    </div>
                                    <span className="text-[10px] font-body italic text-gray-400">
                                        {deliveryMethod === 'delivery' ? 'Discussed on WhatsApp' : 'GHS 0.00'}
                                    </span>
                                </div>
                                <div className="flex items-center justify-between text-gray-900 pt-2 border-t border-gray-200">
                                    <span className="text-[11px] uppercase tracking-[0.3em] font-black">Total</span>
                                    <span className="text-2xl font-body font-black text-blue-600 tracking-tight">
                                        GHS {(cartTotal + DELIVERY_FEE).toLocaleString()}.00
                                    </span>
                                </div>
                            </>
                        )}
                    </div>

                    <button
                        onClick={handleCheckout}
                        disabled={cartItems.length === 0 || isSubmitting}
                        className="w-full bg-gray-900 hover:bg-blue-600 text-white py-4 rounded-xl font-bold uppercase tracking-[0.2em] text-[11px] flex items-center justify-center gap-3 transition-all duration-300 shadow-xl active:scale-[0.98] disabled:opacity-50"
                    >
                        <div className="relative py-4 flex flex-col items-center justify-center gap-1">
                            {isSubmitting ? (
                                <Loader2 className="w-5 h-5 animate-spin text-white" />
                            ) : cartItems.length > 0 ? (
                                <>
                                    <div className="flex items-center gap-3">
                                        <CheckCircle size={18} strokeWidth={2.5} />
                                        <span className="text-[11px] uppercase tracking-[0.2em] font-bold">
                                            Complete via WhatsApp
                                        </span>
                                    </div>
                                </>
                            ) : (
                                <span className="text-[11px] uppercase tracking-[0.2em] font-bold">
                                    Add items to cart
                                </span>
                            )}
                        </div>
                    </button>
                </div>
            </div>
        </>
    );
};

export default CartDrawer;
