import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ArrowLeft, ShoppingCart, Minus, Plus, Loader2 } from 'lucide-react';
import { useCart } from '../context/CartContext';
import { formatPrice, formatCondition } from '../utils/helpers';

const ProductDetailPage = () => {
    const { id } = useParams();
    const [product, setProduct] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [activeImageIndex, setActiveImageIndex] = useState(0);
    const [quantity, setQuantity] = useState(1);
    const { addToCart } = useCart();

    // Fetch product (using mock data for now, can be connected to API later)
    useEffect(() => {
        const fetchProduct = async () => {
            setLoading(true);
            setError(null);

            try {
                // Simulate API call with timeout
                await new Promise(resolve => setTimeout(resolve, 500));

                // In a real app, this would be an API call
                // For now, we'll use the mock data from useProducts hook
                // This is a placeholder - in production, fetch from your API
                const mockProducts = await import('../services/mockData').then(m => m.default);
                const foundProduct = mockProducts.find(p => p.id === parseInt(id));

                if (foundProduct) {
                    setProduct(foundProduct);
                } else {
                    setError('Product not found');
                }
            } catch (err) {
                console.error('Error fetching product:', err);
                setError('Failed to load product. Please try again.');
            } finally {
                setLoading(false);
            }
        };

        fetchProduct();
    }, [id]);

    useEffect(() => {
        window.scrollTo(0, 0);
    }, []);

    const handleAddToCart = () => {
        if (!product) return;

        // Get primary image or first image
        const primaryImage = Array.isArray(product.imageUrls)
            ? product.imageUrls[0]
            : product.imageUrls || '/placeholder.png';

        for (let i = 0; i < quantity; i++) {
            addToCart({
                id: product.id,
                name: `${product.brand} ${product.model}`,
                price: product.price,
                imageUrls: Array.isArray(product.imageUrls) ? product.imageUrls : [primaryImage],
                category: product.category
            });
        }
        setQuantity(1);
    };

    // Get all images
    const getAllImages = () => {
        if (!product) return [];
        if (Array.isArray(product.imageUrls)) return product.imageUrls;
        if (typeof product.imageUrls === 'string' && product.imageUrls.includes(',')) {
            return product.imageUrls.split(',').map(url => url.trim());
        }
        return [product.imageUrls];
    };

    const images = getAllImages();

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center min-h-screen bg-gray-50">
                <Loader2 className="w-12 h-12 text-gray-900 animate-spin" />
                <p className="mt-4 text-gray-500">Loading product...</p>
            </div>
        );
    }

    if (error) {
        return (
            <div className="flex flex-col items-center justify-center min-h-screen bg-gray-50">
                <p className="text-red-500 mb-4">{error}</p>
                <Link to="/" className="px-6 py-3 bg-gray-900 text-white rounded-full">
                    Back to Shop
                </Link>
            </div>
        );
    }

    if (!product) {
        return (
            <div className="flex flex-col items-center justify-center min-h-screen bg-gray-50">
                <h2 className="text-xl font-bold mb-4">Item not found</h2>
                <Link to="/" className="px-6 py-3 bg-gray-900 text-white rounded-full">
                    Return to Shop
                </Link>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Header */}
            <div className="bg-gray-50/80 backdrop-blur-md sticky top-0 z-40 px-6 py-4 flex items-center gap-4">
                <Link to="/" className="p-2 hover:bg-white rounded-full shadow-sm transition-all active:scale-95">
                    <ArrowLeft size={20} className="text-gray-900" />
                </Link>
                <h1 className="font-heading text-xl text-gray-900 truncate">Product Details</h1>
            </div>

            {/* Content */}
            <div className="max-w-6xl mx-auto px-4 py-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* Images */}
                    <div>
                        {/* Main Image */}
                        <div className="aspect-square bg-gray-200 rounded-xl overflow-hidden mb-4">
                            <img
                                src={images[activeImageIndex] || '/placeholder.png'}
                                alt={`${product.brand} ${product.model}`}
                                className="w-full h-full object-cover"
                            />
                        </div>

                        {/* Thumbnails */}
                        {images.length > 1 && (
                            <div className="grid grid-cols-4 gap-2">
                                {images.map((img, index) => (
                                    <button
                                        key={index}
                                        onClick={() => setActiveImageIndex(index)}
                                        className={`aspect-square rounded-lg overflow-hidden border-2 ${activeImageIndex === index ? 'border-gray-900' : 'border-transparent'
                                            }`}
                                    >
                                        <img
                                            src={img}
                                            alt={`${product.brand} ${product.model} ${index + 1}`}
                                            className="w-full h-full object-cover"
                                        />
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Info */}
                    <div className="flex flex-col">
                        <div className="mb-8">
                            <p className="font-body text-[10px] uppercase tracking-[0.2em] text-gray-400 font-bold mb-2">
                                {product.category || 'Gadget'}
                            </p>
                            <h1 className="font-heading text-3xl md:text-5xl text-gray-900 mb-4 leading-tight">
                                {product.brand} {product.model}
                            </h1>
                            <p className="font-body text-3xl font-bold text-blue-600">
                                {formatPrice(product.price)}
                            </p>
                        </div>

                        {/* Condition Badge */}
                        <div className="mb-6">
                            <span className={`inline-block px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide ${product.condition === 'NEW'
                                    ? 'bg-blue-100 text-blue-800'
                                    : product.condition === 'UK_USED'
                                        ? 'bg-green-100 text-green-800'
                                        : 'bg-yellow-100 text-yellow-800'
                                }`}>
                                {formatCondition(product.condition)}
                            </span>
                        </div>

                        {/* Specs */}
                        <div className="mb-6">
                            <h3 className="font-bold text-gray-900 mb-3">Specifications</h3>
                            <div className="space-y-2">
                                {product.processor && (
                                    <div className="flex items-center text-sm text-gray-600">
                                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full mr-2 flex-shrink-0"></span>
                                        <span className="capitalize">Processor: {product.processor}</span>
                                    </div>
                                )}
                                {product.ram && (
                                    <div className="flex items-center text-sm text-gray-600">
                                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full mr-2 flex-shrink-0"></span>
                                        <span className="capitalize">RAM: {product.ram}</span>
                                    </div>
                                )}
                                {product.storage && (
                                    <div className="flex items-center text-sm text-gray-600">
                                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full mr-2 flex-shrink-0"></span>
                                        <span className="capitalize">Storage: {product.storage}</span>
                                    </div>
                                )}
                                {product.display && (
                                    <div className="flex items-center text-sm text-gray-600">
                                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full mr-2 flex-shrink-0"></span>
                                        <span className="capitalize">Display: {product.display}</span>
                                    </div>
                                )}
                                {product.battery && (
                                    <div className="flex items-center text-sm text-gray-600">
                                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full mr-2 flex-shrink-0"></span>
                                        <span className="capitalize">Battery: {product.battery}</span>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Quantity */}
                        <div className="mb-6">
                            <h3 className="font-bold text-gray-900 mb-2">Quantity</h3>
                            <div className="flex items-center gap-4">
                                <button
                                    onClick={() => setQuantity(Math.max(1, quantity - 1))}
                                    className="w-10 h-10 rounded-full border border-gray-300 flex items-center justify-center hover:bg-gray-100"
                                >
                                    <Minus size={18} />
                                </button>
                                <span className="text-xl font-bold w-12 text-center">{quantity}</span>
                                <button
                                    onClick={() => setQuantity(quantity + 1)}
                                    className="w-10 h-10 rounded-full border border-gray-300 flex items-center justify-center hover:bg-gray-100"
                                >
                                    <Plus size={18} />
                                </button>
                            </div>
                        </div>

                        {/* Add to Cart */}
                        <button
                            onClick={handleAddToCart}
                            className="w-full bg-gray-900 hover:bg-blue-600 text-white py-5 rounded-2xl font-bold uppercase tracking-widest text-xs flex items-center justify-center gap-3 transition-all duration-300 shadow-xl active:scale-95"
                        >
                            <ShoppingCart size={20} strokeWidth={2.5} />
                            Add to Cart
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ProductDetailPage;
