import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    LayoutDashboard,
    ShoppingBag,
    Package,
    TrendingUp,
    DollarSign,
    Users,
    LogOut,
    Plus,
    Edit,
    Trash2,
    Search,
    Filter,
    CheckCircle,
    XCircle,
    Clock
} from 'lucide-react';

const ADMIN_PASSWORD = 'admin2024'; // Hardcoded password

const AdminPage = () => {
    const navigate = useNavigate();
    const [isAuthenticated, setIsAuthenticated] = useState(false);
    const [password, setPassword] = useState('');
    const [passwordError, setPasswordError] = useState('');
    const [activeTab, setActiveTab] = useState('dashboard');
    const [products, setProducts] = useState([]);
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');

    // Authentication
    const handleLogin = (e) => {
        e.preventDefault();
        if (password === ADMIN_PASSWORD) {
            setIsAuthenticated(true);
            setPasswordError('');
            loadData();
        } else {
            setPasswordError('Incorrect password');
        }
    };

    const handleLogout = () => {
        setIsAuthenticated(false);
        setPassword('');
    };

    // Load data from localStorage (mock data)
    const loadData = () => {
        setLoading(true);
        try {
            // Load products from localStorage
            const savedProducts = localStorage.getItem('laptop_connect_products');
            const productsData = savedProducts ? JSON.parse(savedProducts) : [];
            setProducts(productsData);

            // Load orders from localStorage
            const savedOrders = localStorage.getItem('laptop_connect_orders');
            const ordersData = savedOrders ? JSON.parse(savedOrders) : [];
            setOrders(ordersData);
        } catch (error) {
            console.error('Error loading data:', error);
        } finally {
            setLoading(false);
        }
    };

    // Calculate analytics
    const analytics = {
        totalProducts: products.length,
        totalOrders: orders.length,
        totalRevenue: orders.reduce((sum, order) => sum + (order.total || 0), 0),
        pendingOrders: orders.filter(o => o.status === 'pending').length,
        confirmedOrders: orders.filter(o => o.status === 'confirmed').length,
        completedOrders: orders.filter(o => o.status === 'completed').length
    };

    // Filter orders
    const filteredOrders = orders.filter(order => {
        const matchesSearch = order.orderNumber?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            order.customerName?.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesStatus = statusFilter === 'all' || order.status === statusFilter;
        return matchesSearch && matchesStatus;
    });

    // Filter products
    const filteredProducts = products.filter(product => {
        return product.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            product.brand?.toLowerCase().includes(searchTerm.toLowerCase());
    });

    // Delete product
    const handleDeleteProduct = (productId) => {
        if (!confirm('Are you sure you want to delete this product?')) return;

        try {
            const updatedProducts = products.filter(p => p.id !== productId);
            setProducts(updatedProducts);
            localStorage.setItem('laptop_connect_products', JSON.stringify(updatedProducts));
        } catch (error) {
            console.error('Error deleting product:', error);
            alert('Failed to delete product');
        }
    };

    // Update order status
    const handleUpdateOrderStatus = async (orderId, newStatus) => {
        try {
            const updatedOrders = orders.map(order =>
                order.id === orderId ? { ...order, status: newStatus } : order
            );
            setOrders(updatedOrders);
            localStorage.setItem('laptop_connect_orders', JSON.stringify(updatedOrders));
        } catch (error) {
            console.error('Error updating order:', error);
            alert('Failed to update order status');
        }
    };

    if (!isAuthenticated) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 px-6">
                <div className="w-full max-w-md animate-fade-in">
                    <div className="bg-white rounded-2xl shadow-2xl p-8 md:p-12 border border-gray-200">
                        {/* Logo/Brand */}
                        <div className="text-center mb-8">
                            <h1 className="font-heading text-3xl md:text-4xl uppercase tracking-tighter text-gray-900">
                                Laptop <span className="text-blue-600 italic">Connect</span> Admin
                            </h1>
                            <p className="text-[10px] text-gray-400 uppercase tracking-[0.4em] mt-2 font-bold">
                                Management Dashboard
                            </p>
                        </div>

                        {/* Login Form */}
                        <form onSubmit={handleLogin} className="space-y-6">
                            <div className="space-y-2">
                                <label className="text-[11px] uppercase tracking-[0.3em] text-gray-900 font-bold">
                                    Admin Password
                                </label>
                                <input
                                    type="password"
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                    placeholder="Enter password"
                                    className="w-full bg-gray-50 border-2 border-gray-200 rounded-full px-6 py-4 text-[14px] focus:border-blue-600 focus:bg-white focus:outline-none focus:shadow-lg transition-all"
                                />
                                {passwordError && (
                                    <p className="text-red-500 text-[10px] uppercase tracking-widest font-bold">
                                        {passwordError}
                                    </p>
                                )}
                            </div>

                            <button
                                type="submit"
                                className="w-full bg-gray-900 hover:bg-blue-600 text-white py-4 rounded-full hover:shadow-xl hover:-translate-y-1 transition-all duration-300 font-bold text-[11px] uppercase tracking-[0.3em]"
                            >
                                Login
                            </button>
                        </form>

                        <p className="text-center text-[9px] text-gray-400 uppercase tracking-widest mt-6">
                            Enter your admin password to continue
                        </p>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Header */}
            <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
                <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <ShoppingBag className="text-blue-600" size={24} />
                        <h1 className="font-heading text-xl uppercase text-gray-900 tracking-tighter">
                            Laptop <span className="text-blue-600 italic">Connect</span> Admin
                        </h1>
                    </div>
                    <button
                        onClick={handleLogout}
                        className="flex items-center gap-2 text-[10px] uppercase tracking-[0.3em] text-gray-400 hover:text-gray-900 transition-colors font-bold"
                    >
                        <LogOut size={16} />
                        Logout
                    </button>
                </div>
            </header>

            {/* Main Content */}
            <main className="max-w-7xl mx-auto px-6 py-8">
                {/* Tab Navigation */}
                <div className="flex gap-2 mb-8 overflow-x-auto no-scrollbar">
                    {[
                        { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
                        { id: 'products', label: 'Products', icon: Package },
                        { id: 'orders', label: 'Orders', icon: ShoppingBag },
                    ].map((tab) => {
                        const Icon = tab.icon;
                        return (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`flex items-center gap-2 px-6 py-3 rounded-full border-2 whitespace-nowrap transition-all duration-300 ${activeTab === tab.id
                                    ? 'bg-gray-900 border-gray-900 text-white shadow-lg'
                                    : 'bg-white border-gray-200 text-gray-400 hover:border-gray-900 hover:text-gray-900'
                                    }`}
                            >
                                <Icon size={16} strokeWidth={2} />
                                <span className="text-[11px] uppercase tracking-[0.3em] font-bold">
                                    {tab.label}
                                </span>
                            </button>
                        );
                    })}
                </div>

                {/* Dashboard Tab */}
                {activeTab === 'dashboard' && (
                    <div className="animate-fade-in space-y-8">
                        {/* Search */}
                        <div className="relative mb-6">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                            <input
                                type="text"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                placeholder="Search products or orders..."
                                className="w-full bg-gray-50 border-2 border-gray-200 rounded-full pl-12 pr-6 py-3 text-[11px] focus:border-blue-600 focus:bg-white focus:outline-none focus:shadow-lg transition-all"
                            />
                        </div>

                        {/* Stats Cards */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                            <StatCard
                                icon={Package}
                                label="Total Inventory"
                                value={analytics.totalProducts}
                            />
                            <StatCard
                                icon={ShoppingBag}
                                label="Order Volume"
                                value={analytics.totalOrders}
                            />
                            <StatCard
                                icon={DollarSign}
                                label="Gross Revenue"
                                value={`GHS ${analytics.totalRevenue.toLocaleString()}`}
                                isGold
                            />
                            <StatCard
                                icon={TrendingUp}
                                label="Completed Orders"
                                value={analytics.completedOrders}
                                isGold
                            />
                        </div>

                        {/* Order Status Breakdown */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
                                <div className="flex items-center gap-3 mb-2">
                                    <Clock className="text-yellow-500" size={20} />
                                    <h3 className="font-bold text-gray-900">Pending</h3>
                                </div>
                                <p className="text-3xl font-bold text-yellow-600">{analytics.pendingOrders}</p>
                            </div>
                            <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
                                <div className="flex items-center gap-3 mb-2">
                                    <CheckCircle className="text-blue-500" size={20} />
                                    <h3 className="font-bold text-gray-900">Confirmed</h3>
                                </div>
                                <p className="text-3xl font-bold text-blue-600">{analytics.confirmedOrders}</p>
                            </div>
                            <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
                                <div className="flex items-center gap-3 mb-2">
                                    <CheckCircle className="text-green-500" size={20} />
                                    <h3 className="font-bold text-gray-900">Completed</h3>
                                </div>
                                <p className="text-3xl font-bold text-green-600">{analytics.completedOrders}</p>
                            </div>
                        </div>
                    </div>
                )}

                {/* Products Tab */}
                {activeTab === 'products' && (
                    <div className="animate-fade-in space-y-6">
                        {/* Header */}
                        <div className="flex items-center justify-between mb-6">
                            <h2 className="text-2xl font-bold text-gray-900">Products</h2>
                            <button
                                onClick={() => navigate('/')}
                                className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-full text-[10px] uppercase font-bold tracking-widest transition-all"
                            >
                                <Plus size={16} />
                                Add Product
                            </button>
                        </div>

                        {/* Products List */}
                        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm">
                            {filteredProducts.length === 0 ? (
                                <div className="p-12 text-center text-gray-500">
                                    <p>No products found</p>
                                </div>
                            ) : (
                                <div className="overflow-x-auto">
                                    <table className="w-full">
                                        <thead className="bg-gray-50">
                                            <tr>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Product</th>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Category</th>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Price</th>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Stock</th>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Actions</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-gray-100">
                                            {filteredProducts.map((product) => (
                                                <tr key={product.id} className="hover:bg-gray-50">
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center gap-3">
                                                            {Array.isArray(product.imageUrls) && product.imageUrls[0] && (
                                                                <img
                                                                    src={product.imageUrls[0]}
                                                                    alt={product.name}
                                                                    className="w-12 h-12 object-cover rounded-lg"
                                                                />
                                                            )}
                                                            <div>
                                                                <p className="font-bold text-gray-900">{product.name}</p>
                                                                <p className="text-sm text-gray-500">{product.brand} {product.model}</p>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <span className="px-3 py-1 bg-gray-100 rounded-full text-xs font-medium text-gray-600">
                                                            {product.category || 'Gadget'}
                                                        </span>
                                                    </td>
                                                    <td className="px-6 py-4 font-bold text-gray-900">
                                                        GHS {product.price.toLocaleString()}
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <span className={`px-3 py-1 rounded-full text-xs font-medium ${product.availability ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                                                            }`}>
                                                            {product.availability ? 'Available' : 'Sold Out'}
                                                        </span>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center gap-2">
                                                            <button
                                                                onClick={() => navigate(`/product/${product.id}`)}
                                                                className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                                                title="View"
                                                            >
                                                                <Search size={16} />
                                                            </button>
                                                            <button
                                                                onClick={() => handleDeleteProduct(product.id)}
                                                                className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                                                title="Delete"
                                                            >
                                                                <Trash2 size={16} />
                                                            </button>
                                                        </div>
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            )}
                        </div>
                    </div>
                )}

                {/* Orders Tab */}
                {activeTab === 'orders' && (
                    <div className="animate-fade-in space-y-6">
                        {/* Header with Filter */}
                        <div className="flex items-center justify-between mb-6">
                            <h2 className="text-2xl font-bold text-gray-900">Orders</h2>
                            <div className="flex items-center gap-4">
                                <div className="relative">
                                    <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                                    <select
                                        value={statusFilter}
                                        onChange={(e) => setStatusFilter(e.target.value)}
                                        className="appearance-none bg-gray-50 border-2 border-gray-200 rounded-full pl-10 pr-10 py-2 text-[11px] focus:border-blue-600 focus:bg-white focus:outline-none focus:shadow-lg transition-all cursor-pointer"
                                    >
                                        <option value="all">All Status</option>
                                        <option value="pending">Pending</option>
                                        <option value="confirmed">Confirmed</option>
                                        <option value="completed">Completed</option>
                                    </select>
                                </div>
                            </div>
                        </div>

                        {/* Orders List */}
                        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm">
                            {filteredOrders.length === 0 ? (
                                <div className="p-12 text-center text-gray-500">
                                    <p>No orders found</p>
                                </div>
                            ) : (
                                <div className="overflow-x-auto">
                                    <table className="w-full">
                                        <thead className="bg-gray-50">
                                            <tr>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Order #</th>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Customer</th>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Items</th>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Total</th>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Status</th>
                                                <th className="px-6 py-3 text-left text-[10px] uppercase tracking-widest text-gray-400 font-bold">Date</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-gray-100">
                                            {filteredOrders.map((order) => (
                                                <tr key={order.id} className="hover:bg-gray-50">
                                                    <td className="px-6 py-4 font-mono text-sm text-gray-600">
                                                        {order.orderNumber}
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div>
                                                            <p className="font-bold text-gray-900">{order.customerName}</p>
                                                            <p className="text-sm text-gray-500">{order.customerPhone}</p>
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4 text-sm text-gray-600">
                                                        {order.items?.length} item{order.items?.length !== 1 ? 's' : ''}
                                                    </td>
                                                    <td className="px-6 py-4 font-bold text-gray-900">
                                                        GHS {order.total?.toLocaleString()}
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <select
                                                            value={order.status}
                                                            onChange={(e) => handleUpdateOrderStatus(order.id, e.target.value)}
                                                            className={`px-3 py-1 rounded-full text-xs font-medium cursor-pointer ${order.status === 'pending' ? 'bg-yellow-100 text-yellow-700' :
                                                                    order.status === 'confirmed' ? 'bg-blue-100 text-blue-700' :
                                                                        'bg-green-100 text-green-700'
                                                                }`}
                                                        >
                                                            <option value="pending">Pending</option>
                                                            <option value="confirmed">Confirmed</option>
                                                            <option value="completed">Completed</option>
                                                        </select>
                                                    </td>
                                                    <td className="px-6 py-4 text-sm text-gray-500">
                                                        {new Date(order.createdAt).toLocaleDateString()}
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
};

// Stat Card Component
const StatCard = ({ icon: Icon, label, value, isGold }) => (
    <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm hover:shadow-md transition-shadow">
        <div className="flex items-center gap-3">
            <Icon className={isGold ? 'text-blue-600' : 'text-gray-400'} size={24} />
            <div>
                <p className="text-[10px] uppercase tracking-[0.3em] text-gray-400 font-bold mb-1">
                    {label}
                </p>
                <p className={`text-2xl font-bold ${isGold ? 'text-blue-600' : 'text-gray-900'}`}>
                    {value}
                </p>
            </div>
        </div>
    </div>
);

export default AdminPage;
