import { useState } from 'react';
import { Link } from 'react-router-dom';
import { ShoppingCart } from 'lucide-react';
import { useCart } from '../context/CartContext';
import { formatPrice, formatCondition } from '../utils/helpers';

const ProductCard = ({ product }) => {
    const [imageError, setImageError] = useState(false);
    const [imageLoading, setImageLoading] = useState(true);
    const { addToCart } = useCart();

    // Get first image URL
    const getImageUrl = () => {
        if (!product.imageUrls) return '';

        // If it's a string with commas, split and take first one
        if (typeof product.imageUrls === 'string' && product.imageUrls.includes(',')) {
            return product.imageUrls.split(',')[0].trim();
        }

        // If it's already a string without commas, return it
        if (typeof product.imageUrls === 'string') {
            return product.imageUrls.trim();
        }

        // If it's an array, return first element
        if (Array.isArray(product.imageUrls) && product.imageUrls.length > 0) {
            return product.imageUrls[0].trim();
        }

        // For any other type, convert to string
        return String(product.imageUrls).trim();
    };

    const imageUrl = getImageUrl();

    const handleImageError = () => {
        setImageError(true);
        setImageLoading(false);
    };

    const handleImageLoad = () => {
        setImageLoading(false);
    };

    const handleAddToCart = (e) => {
        e.preventDefault();
        e.stopPropagation();

        addToCart({
            id: product.id,
            name: `${product.brand} ${product.model}`,
            price: product.price,
            imageUrls: Array.isArray(product.imageUrls) ? product.imageUrls : [imageUrl],
            category: product.category
        });
    };

    // Helper to render relevant specs based on available data
    const renderSpecs = () => {
        // If we have new 'specs' object, use it
        if (product.specs) {
            // Prioritize certain common specs for display on card if they exist
            const priorityKeys = ['processor', 'ram', 'storage', 'graphics', 'display', 'screen', 'battery', 'color'];
            const specEntries = Object.entries(product.specs);

            // Filter detailed boolean flags or very long text for card view (optional)
            const displaySpecs = specEntries.filter(([key, value]) => {
                const lowerKey = key.toLowerCase();
                // Skip internal-sounding keys or booleans for main card text (optional)
                if (lowerKey.startsWith('has')) return false;
                // Prioritize showing only a few items
                return true;
            });

            // Sort to show priority keys first
            displaySpecs.sort(([keyA], [keyB]) => {
                const idxA = priorityKeys.indexOf(keyA.toLowerCase());
                const idxB = priorityKeys.indexOf(keyB.toLowerCase());
                if (idxA !== -1 && idxB !== -1) return idxA - idxB;
                if (idxA !== -1) return -1;
                if (idxB !== -1) return 1;
                return 0;
            });

            // Take top 2
            return (
                <div className="space-y-1 mb-4">
                    {displaySpecs.slice(0, 2).map(([key, value]) => (
                        <div key={key} className="flex items-center text-sm text-gray-500">
                            <span className="w-1.5 h-1.5 bg-blue-400 rounded-full mr-2 flex-shrink-0"></span>
                            <span className="capitalize truncate">
                                {key}: {String(value)}
                            </span>
                        </div>
                    ))}
                </div>
            );
        }

        // Fallback for old data structure
        return (
            <div className="space-y-1 mb-4">
                {/* Show Processor if available */}
                {product.processor && (
                    <div className="flex items-center text-sm text-gray-500">
                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full mr-2 flex-shrink-0"></span>
                        {product.processor}
                    </div>
                )}
                {/* Show RAM if available */}
                {product.ram && (
                    <div className="flex items-center text-sm text-gray-500">
                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full mr-2 flex-shrink-0"></span>
                        {product.ram}
                    </div>
                )}
                {/* Show Storage if available */}
                {product.storage && (
                    <div className="flex items-center text-sm text-gray-500">
                        <span className="w-1.5 h-1.5 bg-blue-400 rounded-full mr-2 flex-shrink-0"></span>
                        {product.storage}
                    </div>
                )}
            </div>
        );
    };

    return (
        <Link to={`/product/${product.id}`} className="group flex flex-col h-full">
            {/* Image Container - Seamless and Premium */}
            <div className="relative aspect-square bg-white rounded-2xl overflow-hidden mb-4 shadow-sm group-hover:shadow-md transition-all duration-500">
                {imageLoading && (
                    <div className="absolute inset-0 flex items-center justify-center bg-gray-100">
                        <div className="w-8 h-8 border-2 border-gray-200 border-t-transparent rounded-full animate-spin"></div>
                    </div>
                )}

                {imageError ? (
                    <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400">
                        <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.75 17L9 20l-1 1h8l-1-1h8l1 1M3 13h18" />
                        </svg>
                        <span className="text-sm">No image available</span>
                    </div>
                ) : (
                    <img
                        src={imageUrl}
                        alt={`${product.brand} ${product.model}`}
                        className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                        onError={handleImageError}
                        onLoad={handleImageLoad}
                    />
                )}

                {/* Category Badge */}
                <div className="absolute top-3 left-3">
                    <span className="px-2.5 py-1 bg-white/90 backdrop-blur-md rounded-full text-[9px] font-bold uppercase tracking-widest text-gray-900 shadow-sm">
                        {product.category || 'Gadget'}
                    </span>
                </div>

                {/* Availability Badge */}
                <div className={`absolute top-3 right-3 px-2 py-1 text-xs font-medium rounded ${product.availability
                        ? 'bg-green-100 text-green-700'
                        : 'bg-red-100 text-red-700'
                    }`}>
                    {product.availability ? 'Available' : 'Sold Out'}
                </div>
            </div>

            {/* Product Info */}
            <div className="flex flex-col flex-1 px-1">
                <h3 className="font-heading text-lg text-gray-900 mb-2 line-clamp-1 leading-tight group-hover:text-blue-600 transition-colors">
                    {product.brand} {product.model}
                </h3>

                {/* Condition Badge */}
                <div className="mb-3">
                    <span className={`inline-block px-2 py-1 text-xs font-medium rounded ${product.condition === 'NEW'
                            ? 'bg-blue-100 text-blue-800'
                            : product.condition === 'UK_USED'
                                ? 'bg-green-100 text-green-800'
                                : 'bg-yellow-100 text-yellow-800'
                        }`}>
                        {formatCondition(product.condition)}
                    </span>
                </div>

                {/* Specs */}
                {renderSpecs()}

                {/* Price and Button */}
                <div className="flex items-center justify-between mt-auto">
                    <div className="text-xl font-bold text-gray-900">
                        {formatPrice(product.price)}
                    </div>
                    <button
                        onClick={handleAddToCart}
                        className="w-9 h-9 bg-gray-900 text-white rounded-full flex items-center justify-center hover:bg-blue-600 transition-colors shadow-lg active:scale-95"
                    >
                        <ShoppingCart size={16} strokeWidth={2.5} />
                    </button>
                </div>
            </div>
        </Link>
    );
};

export default ProductCard;
